                document.getElementById('otoha-daily-value').innerText = daily.displayValue;
                document.getElementById('otoha-daily-max').innerText = max.displayValue;
                const dailyPercentage = max.numericValue > 0 ? (daily.numericValue / max.numericValue) * 100 : 0;
                document.getElementById('otoha-daily-gauge-bar').style.width = `${Math.min(100, Math.max(0, dailyPercentage))}%`;
            }

