            const setsunaData = SafeGetValue(characterData, '神崎刹那');
            if (setsunaData) {
                const corruption = parseValue(SafeGetValue(setsunaData, '堕落度', '0'));
                const daily = parseValue(SafeGetValue(setsunaData, '今日堕落度上升值', '0'));
                const max = parseValue(SafeGetValue(setsunaData, '每日堕落度上限', '10'));

                document.getElementById('setsuna-corruption-value').innerText = corruption.displayValue;
                const corruptionPercentage = Math.min(100, (corruption.numericValue / 100) * 100);
                document.getElementById('setsuna-corruption-bar').style.width = `${Math.max(0, corruptionPercentage)}%`;

                document.getElementById('setsuna-daily-value').innerText = daily.displayValue;
                document.getElementById('setsuna-daily-max').innerText = max.displayValue;
                const dailyPercentage = max.numericValue > 0 ? (daily.numericValue / max.numericValue) * 100 : 0;
                document.getElementById('setsuna-daily-gauge-bar').style.width = `${Math.min(100, Math.max(0, dailyPercentage))}%`;
            }

            const otohaData = SafeGetValue(characterData, '水无月音羽');
            if (otohaData) {
                const corruption = parseValue(SafeGetValue(otohaData, '堕落度', '0'));
                const daily = parseValue(SafeGetValue(otohaData, '今日堕落度上升值', '0'));
                const max = parseValue(SafeGetValue(otohaData, '每日堕落度上限', '10'));

                document.getElementById('otoha-corruption-value').innerText = corruption.displayValue;
                const corruptionPercentage = Math.min(100, (corruption.numericValue / 100) * 100);
                document.getElementById('otoha-corruption-bar').style.width = `${Math.max(0, corruptionPercentage)}%`;

                document.getElementById('otoha-daily-value').innerText = daily.displayValue;
                document.getElementById('otoha-daily-max').innerText = max.displayValue;
                const dailyPercentage = max.numericValue > 0 ? (daily.numericValue / max.numericValue) * 100 : 0;
                document.getElementById('otoha-daily-gauge-bar').style.width = `${Math.min(100, Math.max(0, dailyPercentage))}%`;
            }

        } catch (error) {
            const container = document.querySelector('.notebook-container');
            if (container) {
                container.innerHTML = `<summary>手札加载失败</summary><div style='color:red; padding:10px;'>错误: ${error.message}</div>`;
            }
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);

</script>
</body>
</html>
